SELECT name,group_name,description,updated_at FROM product_category ORDER BY group_name,name;
SELECT source,status,count(*) FROM product_category_assignment GROUP BY 1,2;
SELECT a.product_name_key,c.name,c.group_name,a.status,a.confidence FROM product_category_assignment a LEFT JOIN product_category c ON c.id=a.product_category_id WHERE a.product_name_key LIKE '%porterhouse%';
SELECT count(*) lines,count(quantity) quantities,count(cost) costs,count(unit_of_measurement_name) units,count(recipe_id) recipe_ids,count(*) FILTER(WHERE reason IS NULL OR btrim(reason)='') missing_reasons,count(a.product_name_key) direct_assignments, min(wastage_date),max(wastage_date) FROM canonical_wastage w LEFT JOIN product_category_assignment a USING(product_name_key) WHERE w.superseded_at IS NULL;
SELECT source_system,count(*) rows,count(DISTINCT product_id) ids,count(category) categories,count(reporting_group) reporting_groups,count(*) FILTER(WHERE is_modifier) modifiers,min(recorded_at),max(recorded_at) FROM canonical_product WHERE superseded_at IS NULL GROUP BY 1;
SELECT source_system,count(*),count(DISTINCT source_product_id),count(category) FROM source_product WHERE superseded_at IS NULL GROUP BY 1;
SELECT count(*) rows,count(NULLIF(product_number,'')) product_numbers,count(NULLIF(sku,'')) skus,count(NULLIF(category_name,'')) categories,count(NULLIF(register_name,'')) registers,count(site_number) sites,min(trading_date),max(trading_date) FROM canonical_sale_item WHERE superseded_at IS NULL;
SELECT count(*) links,count(DISTINCT recipe_id) recipes,count(lightspeed_product_id) pos_ids,count(*) FILTER(WHERE is_recipe_active=false) inactive FROM canonical_sale_recipe_link WHERE superseded_at IS NULL;
SELECT count(*) names_with_multiple_recipes FROM (SELECT lower(regexp_replace(btrim(sale_item_stock_description),'\s+',' ','g')) name FROM canonical_sale_recipe_link WHERE superseded_at IS NULL GROUP BY 1 HAVING count(DISTINCT recipe_id)>1) t;
SELECT item_name,string_agg(DISTINCT category_name,' | ') categories FROM canonical_sale_item WHERE superseded_at IS NULL GROUP BY 1 HAVING count(DISTINCT category_name)>1 ORDER BY 1 LIMIT 40;
SELECT lower(btrim(name)) name,count(DISTINCT source_record_ref) identities,string_agg(DISTINCT category,' | ') categories FROM source_product WHERE superseded_at IS NULL GROUP BY 1 HAVING count(DISTINCT source_record_ref)>1 ORDER BY 2 DESC LIMIT 30;
SELECT product_name_key,quantity,cost,reason,unit_of_measurement_name,recipe_id,supplier_name FROM canonical_wastage WHERE superseded_at IS NULL ORDER BY wastage_date DESC,product_name_key LIMIT 35;
SELECT product_name,category,reporting_group,is_modifier FROM canonical_product WHERE superseded_at IS NULL AND (product_name ~* 'coffee|latte|breakfast|cafe|café|shirt|porterhouse|chips|pilsner') ORDER BY product_name LIMIT 50;
